// Normalize Apify results, extract useful lead fields, and remove duplicates.
const incoming = $input.all();
const config = $('Search Parameters').first().json;
let records = [];

// Unwrap the Apify response — handle every known shape.
for (const item of incoming) {
  const value = item.json;
  if (Array.isArray(value)) {
    records.push(...value);
  } else if (Array.isArray(value?.data)) {
    records.push(...value.data);
  } else if (Array.isArray(value?.items)) {
    records.push(...value.items);
  } else if (Array.isArray(value?.results)) {
    records.push(...value.results);
  } else if (Array.isArray(value?.output)) {
    records.push(...value.output);
  } else if (value && typeof value === 'object' && (value.title || value.name || value.placeId)) {
    // Looks like a single place object
    records.push(value);
  } else if (value && typeof value === 'object') {
    // Unknown wrapper — try all array-valued keys
    const arrayKey = Object.keys(value).find(k => Array.isArray(value[k]));
    if (arrayKey) records.push(...value[arrayKey]);
    else records.push(value);
  }
}

function str(v) {
  if (v === undefined || v === null) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'number' || typeof v === 'boolean') return String(v);
  if (Array.isArray(v)) return v.map(str).filter(Boolean).join(', ');
  if (typeof v === 'object') return v.email || v.phone || v.url || v.link || JSON.stringify(v);
  return String(v);
}

function firstStr(...values) {
  for (const value of values) {
    if (Array.isArray(value) && value.length) return str(value[0]);
    if (value !== undefined && value !== null && value !== '') return str(value);
  }
  return '';
}

function listStr(value) {
  if (!value) return '';
  if (Array.isArray(value)) {
    return value.map(v => str(v)).filter(Boolean).join(', ');
  }
  return str(value);
}

const normalized = records.map(place => {
  if (!place || typeof place !== 'object') return null;

  const emails = firstStr(
    place.email,
    place.emails,
    place.contactDetails?.emails,
    place.companyContacts?.emails
  );

  const phones = firstStr(
    place.phone,
    place.phoneNumber,
    place.phones,
    place.contactDetails?.phones
  );

  const facebook = firstStr(
    place.facebook,
    place.facebookUrl,
    place.socials?.facebook,
    place.contactDetails?.facebook
  );

  const instagram = firstStr(
    place.instagram,
    place.instagramUrl,
    place.socials?.instagram,
    place.contactDetails?.instagram
  );

  const linkedin = firstStr(
    place.linkedin,
    place.linkedinUrl,
    place.socials?.linkedin,
    place.contactDetails?.linkedin
  );

  const websiteVal = firstStr(place.website, place.url?.includes?.('google') ? '' : place.url);

  return {
    businessName: firstStr(place.title, place.name),
    category: firstStr(place.categoryName, place.category, place.categories),
    address: firstStr(place.address, place.street),
    city: firstStr(place.city),
    state: firstStr(place.state),
    postalCode: firstStr(place.postalCode, place.zip),
    country: firstStr(place.countryCode, place.country),
    phone: listStr(phones),
    email: listStr(emails),
    website: String(websiteVal || ''),
    googleMapsUrl: firstStr(place.url, place.placeUrl),
    rating: firstStr(place.totalScore, place.rating),
    reviewsCount: firstStr(place.reviewsCount, place.numberOfReviews),
    facebook: listStr(facebook),
    instagram: listStr(instagram),
    linkedin: listStr(linkedin),
    hasWebsite: websiteVal ? 'Yes' : 'No',
    searchQuery: config.searchQuery || '',
    searchLocation: config.location || '',
    scrapedAt: new Date().toISOString()
  };
}).filter(Boolean);

const filtered = normalized.filter(lead => {
  if (!lead.businessName) return false;
  if (!config.onlyWithContact) return true;
  return Boolean(lead.phone || lead.email || lead.website);
});

const seen = new Set();
const unique = filtered.filter(lead => {
  const key = [
    String(lead.businessName || '').toLowerCase().trim(),
    String(lead.phone || '').toLowerCase().trim(),
    String(lead.website || '').toLowerCase().trim()
  ].join('|');

  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

if (unique.length === 0) {
  const debugInfo = {
    incomingItems: incoming.length,
    rawRecords: records.length,
    afterNormalize: normalized.length,
    afterFilter: filtered.length,
    sampleRaw: records.length > 0 ? JSON.stringify(Object.keys(records[0])).substring(0, 200) : 'none'
  };
  throw new Error(
    'No leads survived cleaning. Debug: ' + JSON.stringify(debugInfo) +
    '. Check that the Apify scraper returned results and the response format is correct.'
  );
}

return unique.map(lead => ({ json: lead }));

// Produce a downloadable CSV file in the execution output.
const rows = $input.all().map(item => item.json);

if (!rows.length) {
  throw new Error('No leads were returned. Try another search term/location or disable onlyWithContact.');
}

const headers = [
  'businessName', 'category', 'address', 'city', 'state', 'postalCode',
  'country', 'phone', 'email', 'website', 'googleMapsUrl', 'rating',
  'reviewsCount', 'facebook', 'instagram', 'linkedin', 'hasWebsite',
  'searchQuery', 'searchLocation', 'scrapedAt'
];

const escapeCsv = value => {
  const text = value === undefined || value === null ? '' : String(value);
  return `"${text.replace(/"/g, '""')}"`;
};

const csv = [
  headers.map(escapeCsv).join(','),
  ...rows.map(row => headers.map(key => escapeCsv(row[key])).join(','))
].join('\n');

const stamp = new Date().toISOString().replace(/[:.]/g, '-');

return [{
  json: {
    leadCount: rows.length,
    fileName: `apify-leads-${stamp}.csv`,
    message: 'Open the Binary tab and download the CSV file.'
  },
  binary: {
    data: {
      data: Buffer.from(csv, 'utf8').toString('base64'),
      mimeType: 'text/csv',
      fileName: `apify-leads-${stamp}.csv`,
      fileExtension: 'csv'
    }
  }
}];
